export const NEARBY_FACILITIES = LOCATION_RECORDS.map(({sourceUrl, coordinateDataset, coordinateSourceTime, ...record}) => {
  const coordinateSource = {
    ...COORDINATE_SOURCES[coordinateDataset],
    sourceTime: coordinateSourceTime,
    checkedAt: CHECKED_AT,
    recordId: record.coordinateRecord
  };
  const source = coordinateDataset === 'nparks'
    ? {...coordinateSource, sourceTimeNote: 'Location record update date; no operating observation.'}
    : {
        name: 'SBS Transit station information',
        url: sourceUrl,
        sourceTime: null,
        sourceTimeNote: 'The operator page gives no publication date or current operating observation.',
        checkedAt: CHECKED_AT
      };
  return {
    ...record,
    source,
    coordinateSource,
    operatingStatus: 'unknown',
    statusNote: 'Current availability, maintenance and access hours are unconfirmed.',
    verification: 'source-listed',
    wheelchair: null,
    paidArea: null,
    openingHours: null,
    feeCents: null
  };
});

